"""Client that posts records to the ingestion API."""
import json
import os
import urllib.error
import urllib.request

# The ingestion endpoint is supplied through the environment because it is
# intentionally not recorded anywhere in this repository.
ENDPOINT = (
    os.environ.get("INGESTION_ENDPOINT")
    or os.environ.get("INGESTION_API_URL")
    or os.environ.get("INGESTION_API")
    or ""
)


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        except urllib.error.HTTPError:
            # A non-2xx response means this record was not accepted. Keep
            # going so every record in records.json is attempted.
            continue
    return accepted


def main():
    endpoint = ENDPOINT
    if not endpoint:
        raise SystemExit(
            "error: INGESTION_ENDPOINT is not set "
            "(set INGESTION_ENDPOINT, INGESTION_API_URL, or INGESTION_API)"
        )
    records = load_records()
    accepted = post_records(endpoint, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
